From ce9f30105f06712c67be3c5c8dd814182d2b8b44 Mon Sep 17 00:00:00 2001
From: Peter Lemenkov <lemenkov@gmail.com>
Date: Fri, 21 Sep 2012 16:53:46 +0400
Subject: [PATCH] Fix SAS base32 codec

This fixes issues introduced in commit b2e073c422729ed7807ffcc42012df38ba4b7b78

Signed-off-by: Peter Lemenkov <lemenkov@gmail.com>

diff --git a/c_src/sas_nif.c b/c_src/sas_nif.c
index d804590..f9e9e23 100644
--- a/c_src/sas_nif.c
+++ b/c_src/sas_nif.c
@@ -566,7 +566,7 @@ static int b32(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[])
 	bytes[0] = ((uint8_t*)(bin.data))[0];
 	bytes[1] = ((uint8_t*)(bin.data))[1];
 	bytes[2] = ((uint8_t*)(bin.data))[2] & 0xf0;
-	bits = (bytes[0]  << 24) | (bytes[1] << 16) | (bytes[0] << 0) | 0;
+	bits = (bytes[0]  << 24) | (bytes[1] << 16) | (bytes[2] << 8) | 0;

 	for (i=0,shift=27; i!=4; ++i,shift-=5){
 		n = (bits>>shift) & 31;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrectly using the first byte (`bytes[0]`) twice in the bitwise operation to calculate the `bits` variable, instead of using the third byte (`bytes[2]`). This led to incorrect encoding in the SAS base32 codec, as the data was not being processed as intended.

        Commit message:
        Fix SAS base32 codec

This fixes issues introduced in commit b2e073c422729ed7807ffcc42012df38ba4b7b78

Signed-off-by: Peter Lemenkov <lemenkov@gmail.com>  

        Patch:

 static int b32(ErlNifEnv* env, int argc, const ERL_NIF_TERM argv[])
 {
 	ErlNifBinary bin;
 	ErlNifBinary out;
 	enif_inspect_binary(env, argv[0], &bin);

 	int bits;
 	uint8_t bytes[3];
 	char result[4];
 	int i, n, shift;

 	bytes[0] = ((uint8_t*)(bin.data))[0];
 	bytes[1] = ((uint8_t*)(bin.data))[1];
 	bytes[2] = ((uint8_t*)(bin.data))[2] & 0xf0;
-	bits = (bytes[0]  << 24) | (bytes[1] << 16) | (bytes[0] << 0) | 0;
+	bits = (bytes[0]  << 24) | (bytes[1] << 16) | (bytes[2] << 8) | 0;

 	for (i=0,shift=27; i!=4; ++i,shift-=5){
 		n = (bits>>shift) & 31;
 		result[i] = b32_chars[n];
 	}

 	enif_alloc_binary(4, &out);
 	memcpy(out.data, result, 4);

 	return enif_make_binary(env, &out);
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
- bytes[0] = ((uint8_t*)(bin.data))[0];
- bytes[1] = ((uint8_t*)(bin.data))[1];
- bytes[2] = ((uint8_t*)(bin.data))[2] & 0xf0;
- bits = (bytes[0]  << 24) | (bytes[1] << 16) | (bytes[0] << 0) | 0;
